import {validateAudio,createRecorder} from './audio.js';
const APP_VERSION='2.2.0';
let currentContext={location:'展場',locationDetail:''},updateAvailable=false;
import {checkVocabulary,setVocabulary,EKG,termByName,termById,normalizeEKGRecord} from './ekg.js';
import {helpView} from './help.js';
import * as DB from './db.js';
import {validateCasino,hasFieldRecord,SCHEMA,LOCATIONS,WORKS,tokens,safeUrl,validateRecord,filterRecords,csv,checkBackup,mergeRecords} from './model.js';

const $=s=>document.querySelector(s), main=$('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let casinos=[],records=[],vendors=[],media=new Map(),editor=null,routeToken=0,formTimer,toastTimer,preparedBackup=null,pendingImport=null,heavy=false,uploading=false;
let draftQueue=Promise.resolve(),draftError=null,offlineReady=false;
const objectUrls=new Map(), filters={q:'',vendor:'',tag:'',location:'',kind:'',work:'',state:''};
const id=()=>crypto.randomUUID(), now=()=>new Date().toISOString();
const fmt=t=>{const d=new Date(t);return Number.isFinite(+d)?d.toLocaleString('zh-TW',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'時間未記錄';};
const options=(values,value,empty='')=>(empty?`<option value="">${empty}</option>`:'')+values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');
const tags=(items,cls='')=>(items||[]).map(t=>`<span class="tag ${cls}">${esc(t)}</span>`).join('');

function ekgTags(items){return (items||[]).map(name=>{const t=termByName.get(name);return t?`<button type="button" class="tag ekg-tag" data-action="term" data-term="${esc(t.id)}" aria-label="查看 ${esc(t.term_en)} 說明">${esc(t.term_zh)} · ${esc(t.term_en)}</button>`:'';}).join('');}
function legacyTags(r){return r.legacyTags?.length?`<div class="legacy-tags"><strong>舊標籤待對照（非 EKG）</strong><p>${tags(r.legacyTags)}</p><small>保留原有分類，不自動推定等同哪個 EKG 機制；請閱讀定義後在上方選取。</small></div>`:'';}
function termContent(t){return `<h2>${esc(t.term_en)}</h2><h3>${esc(t.term_zh)}</h3><p>${esc(t.definition_zh)}</p><p lang="en">${esc(t.definition_en)}</p><p class="muted">原文範例：${esc(t.example_game)}</p>${t.notes?`<p class="muted">${esc(t.notes)}</p>`:''}<small>來源：${esc(EKG.source_report)} · p.${t.report_page}<br>${esc(t.source_file)} · 來源項次 ${t.attribute}</small>`;}
function showTerm(tid){const t=termById.get(tid);if(!t)return;let dialog=$('#term-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='term-dialog';dialog.setAttribute('aria-label','EKG 玩法標籤說明');document.body.append(dialog);}dialog.innerHTML='<div class="actions"><button type="button" data-action="close-term" aria-label="關閉玩法說明">關閉</button></div>'+termContent(t);dialog.showModal();}
function glossary(){if(!EKG.terms.length){main.innerHTML=importWelcome('尚未匯入詞彙表');return;}main.innerHTML=pageHead('EKG 中英文詞彙',`已匯入 ${EKG.terms.length} 項；來源與中文翻譯狀態見資料包。`)+`<div class="search"><input id="ekg-query" type="search" aria-label="搜尋 EKG 中英文詞彙" placeholder="搜尋中英文名稱、定義或範例"></div><p id="ekg-count" role="status"></p><div id="ekg-terms"></div>`;renderGlossary();}
function renderGlossary(){const q=($('#ekg-query')?.value||'').trim().toLowerCase();const ts=EKG.terms.filter(t=>[t.term_en,t.term_zh,t.definition_en,t.definition_zh,t.example_game].join(' ').toLowerCase().includes(q));$('#ekg-count').textContent=ts.length+' / '+EKG.terms.length+' 項';$('#ekg-terms').innerHTML=ts.map(t=>`<article class="panel ekg-entry">${termContent(t)}</article>`).join('')||'<p>沒有符合詞彙，試試英文或較短關鍵字。</p>';}
function renderEKGPicker(){if(!editor||!$('#ekg-picker'))return;if(!EKG.terms.length){$('#ekg-picker').innerHTML='<p>尚未匯入詞彙表，可先儲存不含 Tag 的紀錄，之後再補。</p>';return;}const q=($('#ekg-picker-search')?.value||'').trim().toLowerCase();const selected=editor.record.tags;$('#ekg-selected').innerHTML='<p>已選 '+selected.length+' 項（再按一次可取消）</p><div class="tags">'+selected.map(n=>{const t=termByName.get(n);return `<button type="button" data-action="ekg-toggle" data-term="${esc(t.id)}" aria-pressed="true">✓ ${esc(t.term_zh)} · ${esc(t.term_en)} ×</button>`;}).join('')+'</div>';const ts=EKG.terms.filter(t=>(t.term_en+' '+t.term_zh+' '+t.definition_zh).toLowerCase().includes(q));$('#ekg-picker').innerHTML=ts.map(t=>`<div class="ekg-choice"><button type="button" data-action="ekg-toggle" data-term="${esc(t.id)}" aria-pressed="${selected.includes(t.term_en)}">${selected.includes(t.term_en)?'✓':'＋'} ${esc(t.term_zh)}<small>${esc(t.term_en)}</small></button><button type="button" data-action="term" data-term="${esc(t.id)}" aria-label="查看 ${esc(t.term_en)} 說明">說明</button></div>`).join('')||'<p>沒有符合的 EKG 詞彙。</p>';}

function importWelcome(title){return pageHead(title,'這是空白 App；研究資料只在你匯入後存入這台裝置。')+'<section class="panel"><h2>先匯入私人資料包</h2><p>前往「資料與備份」，選擇收到的 JSON 資料包。選檔只在本機讀取，不會上傳網站。</p><button class="primary" data-nav="settings">匯入私人資料包</button><p class="muted">也可以先新增空白紀錄。請勿把私人資料包或備份放上 GitHub。</p><a href="#new">＋ 先新增機台</a></section>';}
function vendorBadge(name){const hue=[...(name||'')].reduce((n,c)=>n+c.charCodeAt(0),0)%360;return `<span class="vendor-badge" style="--vendor-hue:${hue}">${esc(name||'廠商待確認')}</span>`;}
function mediaOrigin(mid){const m=media.get(mid);return m?.origin==='自行加入'||mid.startsWith('photo-')?'自行上傳':'事前網路資料';}
function photoLabel(mid){return `<span class="photo-origin ${mediaOrigin(mid)==='自行上傳'?'own':''}">${mediaOrigin(mid)}</span>`;}
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4800);}
function errorText(err){return err?.name==='QuotaExceededError'?'手機儲存空間不足。這次內容尚未存好，請保留畫面並先備份資料。':err?.message||'操作未完成，請重試。';}
function imageUrl(mid,thumb=false){const m=media.get(mid);if(!m)return '';const blob=thumb?(m.thumbBlob||m.blob):m.blob;if(blob){const key=mid+(thumb?':thumb':':full');if(!objectUrls.has(key))objectUrls.set(key,URL.createObjectURL(blob));return objectUrls.get(key);}const path=thumb?(m.thumbPath||m.path):m.path;return /^assets\/[\w.-]+$/.test(path||'')?path:'';}
function image(mid,thumb=true,cls=''){const m=media.get(mid);const url=imageUrl(mid,thumb);return url?`<img class="${cls}" src="${esc(url)}" alt="${esc(m?.caption||m?.name||'遊戲圖片')}" loading="lazy" data-image="${esc(mid)}">`:'';}
async function refresh(){currentContext=(await DB.get('meta','currentContext'))?.value||{location:'展場',locationDetail:''};casinos=(await DB.get('meta','casinos'))?.value||[];[records,vendors]=await Promise.all([DB.all('records'),DB.all('vendors')]);records=records.map(normalizeEKGRecord);media=new Map((await DB.all('media')).map(m=>[m.id,m]));}
function currentRecord(rid){const r=records.find(r=>r.id===rid);if(!r)throw Error('找不到這筆機台資料。');return r;}
async function saveRecord(record){const r={...record,updatedAt:now(),userEdited:true};validateRecord(r);const changes=[{store:'records',value:r}];if(r.vendor&&!vendors.some(v=>v.name===r.vendor)){changes.push({store:'vendors',value:{id:r.vendor,name:r.vendor,event:'G2E 2026',booth:'',boothStatus:'待確認',boothSource:'',verifiedAt:'',note:''}});}await DB.batch(changes);await refresh();return r;}
function pageHead(title,description,actions=''){return `<div class="pagehead"><div><h1>${esc(title)}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function cover(r){return r.mediaIds.length?`${image(r.mediaIds[0])}<span class="photo-count">${r.mediaIds.length} 張</span>`:'<span class="nopic"><span>▧</span>待補圖片</span>';}
function cards(list){if(!list.length)return '<div class="empty"><h2>沒有符合的紀錄</h2><p>試著清除篩選，或新增一台現場看到的機台。</p><button data-action="reset-filter">清除篩選</button></div>';return `<div class="catalog">${list.map(r=>`<article class="game"><a href="#game/${encodeURIComponent(r.id)}" class="cover" aria-label="查看 ${esc(r.name)}">${cover(r)}</a><div class="game-body"><div class="vendorline">${vendorBadge(r.vendor)} <span>${esc(r.location)}</span></div><h2><a href="#game/${encodeURIComponent(r.id)}">${esc(r.name)}</a></h2><div class="tags">${ekgTags(r.tags.slice(0,2))}${r.legacyTags?.length?tags(['舊標籤待對照'],'gold'):''}${r.priority==='必看'?tags(['必看'],'gold'):''}${hasFieldRecord(r)?tags(['有現場紀錄'],'green'):''}</div></div><div class="game-foot"><button data-action="star" data-id="${esc(r.id)}" aria-pressed="${r.priority==='必看'}">${r.priority==='必看'?'★ 必看中':'☆ 設為必看'}</button><button data-action="seen" data-id="${esc(r.id)}" aria-pressed="${r.seen}">${r.seen?'✓ 已看':'○ 未看'}</button><button data-action="edit" data-id="${esc(r.id)}">編輯紀錄</button></div></article>`).join('')}</div>`;}
function catalog(){if(!records.length){main.innerHTML=importWelcome('你的展場資料庫');return;}const active=records.filter(r=>!r.archived);main.innerHTML=pageHead('遊戲圖鑑',`事前資料與現場觀察，一起收在這裡。`)+`<section class="tools" aria-label="搜尋篩選"><div class="search"><input id="search" type="search" value="${esc(filters.q)}" placeholder="找機台、廠商、玩法或美術風格" aria-label="搜尋資料庫"></div><div class="filters"><select id="filter-vendor" aria-label="篩選廠商">${options([...new Set(active.map(r=>r.vendor))].sort(),filters.vendor,'全部廠商')}</select><select id="filter-location" aria-label="篩選地點">${options(LOCATIONS,filters.location,'所有地點')}</select><select id="filter-state" aria-label="篩選狀態">${options(['必看','未看','已看','有現場紀錄','待補圖'],({'star':'必看','unseen':'未看','seen':'已看','edited':'有現場紀錄','missing':'待補圖'})[filters.state],'所有狀態')}</select><details><summary>更多篩選</summary><div class="filters"><select id="filter-tag" aria-label="篩選玩法">${'<option value="">所有 EKG 標籤</option>'+EKG.terms.map(t=>`<option value="${esc(t.term_en)}" ${filters.tag===t.term_en?'selected':''}>${esc(t.term_zh)} · ${esc(t.term_en)}</option>`).join('')}</select><select id="filter-work" aria-label="篩選作品">${options(WORKS,filters.work,'所有作品')}</select><select id="filter-kind" aria-label="篩選產品類型">${options([...new Set(active.map(r=>r.kind))].sort(),filters.kind,'所有類型')}</select></div></details><button class="compact quiet" data-action="reset-filter">重設</button></div></section><div class="resultbar"><span id="result-count"></span><button class="quiet compact" data-action="csv">匯出篩選表</button></div><div id="results"></div>`;renderResults();}
function filtered(){return filterRecords(records,filters).sort((a,b)=>(b.priority==='必看')-(a.priority==='必看')||a.vendor.localeCompare(b.vendor)||a.name.localeCompare(b.name));}
function renderResults(){const list=filtered();$('#results').innerHTML=cards(list);$('#result-count').textContent=`${list.length} / ${records.filter(r=>!r.archived).length} 筆　·　${list.filter(r=>r.seen).length} 筆已看`;}
function detail(rid){const r=currentRecord(rid);main.innerHTML=`<a class="back" href="#catalog">‹ 返回圖鑑</a>`+pageHead(r.name,`${vendorBadge(r.vendor)} · ${esc(r.kind)} · ${r.id.startsWith('PRE-')?'事前收錄':'自行新增'}`,`<button data-action="edit" data-id="${esc(r.id)}">編輯資料</button><button class="primary" data-action="jump-note">寫筆記</button>`)+`${r.archived?'<p class="notice">這筆資料已封存，可在資料與備份還原。</p>':''}<div class="detail-layout"><section class="panel"><h2>圖片 <small>${r.mediaIds.length} 張</small></h2>${r.mediaIds.length?`<figure class="source-photo">${image(r.mediaIds[0],false,'hero-image')}<figcaption>${photoLabel(r.mediaIds[0])}</figcaption></figure>`:'<div class="empty">沒有圖片，現場可以補拍。</div>'}<div class="gallery">${r.mediaIds.slice(1).map(mid=>`<button data-action="image" data-mid="${esc(mid)}" aria-label="放大圖片">${image(mid)}${photoLabel(mid)}</button>`).join('')}</div><p class="muted">點圖片放大。文章配圖可能包含其他機台；現場照片以原檔保存。</p><button data-action="edit" data-id="${esc(r.id)}">＋ 加入圖片</button></section><section class="panel"><h2>機台資料</h2><dl class="fields"><dt>地點</dt><dd>${esc(r.location)}${r.locationDetail?'\n'+esc(r.locationDetail):''}</dd><dt>廠商</dt><dd>${vendorBadge(r.vendor)}</dd><dt>作品</dt><dd>${esc(r.work)}</dd><dt>說明</dt><dd>${esc(r.description||'尚未填寫')}</dd><dt>Tag</dt><dd><div class="tags">${ekgTags(r.tags)}</div><small>EKG 詞彙分類；不代表 EKG 已認證本遊戲。</small>${legacyTags(r)}</dd><dt>主題、美術風格</dt><dd><div class="tags">${tags(r.styles)}</div>${esc(r.artNotes||'尚未填寫')}</dd><dt>相關連結</dt><dd class="links">${r.links.map((u,i)=>safeUrl(u)?`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(u)}</a>`:'').join('')||'尚未填寫'}</dd><dt>待確認</dt><dd>${esc(r.todo||'無')}</dd></dl><p class="muted">${esc(r.sourceNote||'')} ${r.g2e?'G2E關聯：'+esc(r.g2e)+'。':''}</p><div class="actions"><button data-action="seen" data-id="${esc(r.id)}" aria-pressed="${r.seen}">${r.seen?'✓ 已看過':'標記已看'}</button><button data-action="star" data-id="${esc(r.id)}" aria-pressed="${r.priority==='必看'}">${r.priority==='必看'?'★ 必看中':'☆ 設為必看'}</button></div></section></div><section class="panel" id="note-section"><h2>現場筆記</h2><p class="muted">每次觀察各自保留；事前文章說明不會被筆記覆蓋。長筆記也可從「編輯資料」填寫並自動存草稿。</p>${r.notes.map(n=>`<div class="note"><small>${esc(fmt(n.createdAt))} · ${esc(n.location||'')} ${esc(n.locationDetail||'')}</small><p>${esc(n.text)}</p></div>`).join('')||'<p class="muted">還沒有現場筆記。</p>'}<form class="note-form" id="note-form" data-id="${esc(r.id)}"><textarea name="text" rows="4" placeholder="記下現場看到的玩法、觸發條件，以及想補拍或確認的事情。" aria-label="現場筆記" required></textarea><div class="form-grid"><div class="form-field"><label>觀察地點<select name="location">${options(LOCATIONS,r.location==='事前資料'?'展場':r.location)}</select></label></div><div class="form-field"><label>展會／賭場名稱<input name="locationDetail" placeholder="例如 G2E、某某賭場"></label></div></div><div class="actions"><small id="note-draft-status">輸入後自動存草稿</small><button class="primary" type="submit">儲存筆記</button></div></form></section><section class="panel"><details><summary>事前來源文章（${r.sources?.length||0}筆收錄）</summary>${(r.sources||[]).map(p=>`<div class="source"><small>${esc(p.id)} · ${esc(p.report)}</small><p>${esc(p.text)}</p>${safeUrl(p.url)?`<a href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">${esc(p.sourceType||'來源')}</a>`:''}</div>`).join('')}</details></section>`;main.insertAdjacentHTML('beforeend','<section class="panel"><h2>錄音附件</h2>'+audioList(r)+'</section>');document.querySelectorAll('.note').forEach((el,i)=>{const b=document.createElement('button');b.type='button';b.className='compact';b.textContent='編輯這筆筆記';b.dataset.action='edit-note';b.dataset.id=rid;b.dataset.noteId=r.notes[i].id;el.append(b);});DB.get('drafts','note-'+rid).then(d=>{const form=$('#note-form');if(d&&form?.dataset.id===rid){form.elements.text.value=d.text;form.dataset.noteId=d.noteId||'';form.elements.location.value=d.location;form.elements.locationDetail.value=d.locationDetail;$('#note-draft-status').textContent='已恢復本機草稿';}}).catch(err=>notify(errorText(err)));}
function blankRecord(){return {id:'LOCAL-'+id(),name:'',vendor:filters.vendor||'',kind:'實體遊戲',family:'',location:currentContext.location,locationDetail:currentContext.locationDetail,work:'未確認',description:'',tags:[],styles:[],artNotes:'',mediaIds:[],links:[],sources:[],todo:'',priority:'值得看',seen:false,notes:[],sourceNote:'現場自行新增',createdAt:now(),updatedAt:now(),userEdited:true,archived:false};}
async function edit(rid,token){const key=rid?'edit-'+rid:'new';const draft=await DB.get('drafts',key);if(token!==routeToken)return;const record=normalizeEKGRecord(draft?.record|| (rid?structuredClone(currentRecord(rid)):blankRecord()));editor={key,record,quick:!rid,originalId:rid||'',draftRestored:!!draft};editView();}
function editView(){if(editor?.casino){casinoEditView();return;}const r=editor.record;main.innerHTML=pageHead(editor.originalId?'編輯機台資料':'新增機台',editor.draftRestored?'已恢復上次的本機草稿。':'九個基本欄位；不清楚的內容可以晚點補。')+`<form id="edit-form" class="edit-form"><section class="panel"><div class="form-grid"><div class="form-field"><label for="location">地點</label><select id="location" name="location">${options(LOCATIONS,r.location)}</select></div><div class="form-field"><label for="locationDetail">展會／賭場名稱</label><input id="locationDetail" name="locationDetail" value="${esc(r.locationDetail)}" placeholder="在哪個展會或賭場看到"></div><div class="form-field"><label for="vendor">廠商</label><input id="vendor" name="vendor" list="vendors-list" value="${esc(r.vendor)}" placeholder="可選現有廠商或直接輸入"><datalist id="vendors-list">${vendors.map(v=>`<option value="${esc(v.name)}">`).join('')}</datalist></div><div class="form-field"><label for="name">機台名稱</label><input id="name" name="name" value="${esc(r.name)}" placeholder="不知道名稱可留白，先存照片"></div><div class="form-field"><label for="work">作品</label><select id="work" name="work">${options(WORKS,r.work)}</select></div><div class="form-field"><label for="kind">產品類型</label><input id="kind" name="kind" value="${esc(r.kind)}" list="kinds"><datalist id="kinds">${['實體遊戲','機櫃／硬體','線上遊戲','桌遊／ETG','系列／組合','待確認'].map(t=>`<option value="${t}">`).join('')}</datalist></div><div class="form-field wide"><label for="description">說明</label><textarea class="long" id="description" name="description" placeholder="詳細玩法、觸發條件、特色流程，或現場筆記">${esc(r.description)}</textarea></div><div class="form-field wide"><label>Tag · EKG 中英文清單</label><p class="muted">從已匯入的 ${EKG.terms.length} 項清單選取；點「說明」查定義。</p><input type="search" id="ekg-picker-search" aria-label="搜尋可選 EKG 標籤" placeholder="搜尋中英文玩法"><div id="ekg-selected"></div><div id="ekg-picker" class="ekg-picker"></div>${legacyTags(r)}</div><div class="form-field wide"><label for="styles">主題、美術風格</label><input id="styles" name="styles" value="${esc(r.styles.join('、'))}" placeholder="例如：埃及、木乃伊、卡通、金色"><textarea name="artNotes" aria-label="美術補充說明" placeholder="美術細節或圖片判讀">${esc(r.artNotes)}</textarea></div></div></section><section class="panel"><h2>圖片</h2><p class="muted">保存原始圖片。單張上限25 MB；不會自動上傳雲端。圖片處理完成前請留在此頁。</p><div class="actions"><label class="file-button">拍照<input type="file" id="camera-input" accept="image/*" capture="environment"></label><label class="file-button">從相簿加入<input type="file" id="photo-input" accept="image/*" multiple></label><small id="upload-status"></small></div><div id="uploads" class="uploads" style="margin-top:16px"></div></section><section class="panel"><div class="form-grid"><div class="form-field wide"><label for="links">相關連結</label><textarea id="links" name="links" placeholder="一行一個完整網址，例如 https://…">${esc(r.links.join('\n'))}</textarea></div><div class="form-field wide"><label for="todo">待補拍／待確認</label><textarea id="todo" name="todo" rows="2">${esc(r.todo)}</textarea></div><div class="form-field"><label for="priority">關注程度</label><select id="priority" name="priority">${options(['必看','值得看','順路'],r.priority)}</select></div><div class="form-field"><label for="family">系列／對照名稱</label><input id="family" name="family" value="${esc(r.family||'')}"></div><div class="checkrow"><input type="checkbox" id="seen" name="seen" ${r.seen?'checked':''}><label for="seen">已在現場看過</label></div></div></section><div class="form-footer"><small id="draft-status">${editor.draftRestored?'已恢復草稿':'輸入後自動存草稿'}</small><button type="button" data-action="leave-edit">稍後繼續</button><button type="submit" class="primary" id="save-record">儲存紀錄</button></div><p id="form-error" class="save-error" role="alert"></p><div class="actions"><button type="button" class="quiet" data-action="discard-draft">放棄這份草稿</button>${editor.originalId?`<button type="button" class="quiet danger" data-action="archive" data-id="${esc(r.id)}">封存此筆資料</button>`:''}</div></form>`;renderUploads();renderEKGPicker();mountAudio();quickLayout();}
function readForm(){if(editor?.casino){const f=$('#casino-form');if(f)for(const k of ['name','city','visitedOn','description'])editor.record[k]=f.elements[k].value;return;}const form=$('#edit-form');if(!form||!editor)return;const fd=new FormData(form);for(const k of ['location','locationDetail','vendor','name','work','kind','description','artNotes','todo','priority','family'])editor.record[k]=String(fd.get(k)||'').trim();editor.record.styles=tokens(fd.get('styles'));editor.record.links=String(fd.get('links')||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);editor.record.seen=fd.get('seen')==='on';}
function queueDraft(){if(!editor)return Promise.resolve();readForm();const key=editor.key, record=structuredClone(editor.record);$('#draft-status')&&($('#draft-status').textContent='正在存草稿…');draftQueue=draftQueue.catch(()=>{}).then(()=>DB.put('drafts',{id:key,record,savedAt:now()})).then(()=>{draftError=null;if(editor?.key===key&&$('#draft-status'))$('#draft-status').textContent='草稿已存本機';}).catch(err=>{draftError=err;if($('#draft-status'))$('#draft-status').textContent='草稿尚未存好';if($('#form-error'))$('#form-error').textContent=errorText(err);});return draftQueue;}
async function flushDraft(){clearTimeout(formTimer);await queueDraft();if(draftError)throw draftError;}
function renderUploads(){if(!editor||!$('#uploads'))return;$('#uploads').innerHTML=editor.record.mediaIds.map(mid=>{const m=media.get(mid);return `<div class="upload">${image(mid)}${photoLabel(mid)}<p>${esc(m?.name||'來源圖片')}</p><input data-caption="${esc(mid)}" value="${esc(editor.record.mediaCaptions?.[mid]??m?.caption??'')}" aria-label="圖片說明" placeholder="圖片說明"><button type="button" data-action="remove-media" data-mid="${esc(mid)}">從這筆移除</button></div>`;}).join('');}
async function thumb(blob){const url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,480/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.8));}catch{return null;}finally{URL.revokeObjectURL(url);}}
async function addPhotos(files){if(!editor||uploading)return;uploading=true;const ed=editor;try{await flushDraft();let count=0;for(const file of files){if(file.size>25*1024*1024)throw Error(file.name+' 超過25 MB，請選擇較小照片。');const type=file.type||(/\.hei[cf]$/i.test(file.name)?'image/heic':'');if(!/^image\/(jpeg|png|webp|gif|heic|heif)$/i.test(type))throw Error('目前支援 JPEG、PNG、WebP、GIF、HEIC／HEIF 圖片。');if($('#upload-status'))$('#upload-status').textContent=`處理第 ${count+1} / ${files.length} 張…`;const m={id:'photo-'+id(),name:file.name,type,size:file.size,origin:'自行加入',caption:'',createdAt:now(),blob:new Blob([file],{type}),thumbBlob:await thumb(file)};if(!m.thumbBlob&&/hei[cf]/.test(type))notify('此裝置無法預覽這張HEIC，原檔仍會保存。可另選JPEG版本。');const next={...ed.record,mediaIds:[...ed.record.mediaIds,m.id]};await DB.batch([{store:'media',value:m},{store:'drafts',value:{id:ed.key,record:next,savedAt:now()}}]);media.set(m.id,m);ed.record=next;count++;renderUploads();}if($('#upload-status'))$('#upload-status').textContent=`${count} 張已存本機草稿`;notify('照片已存本機草稿，請儲存紀錄。');}finally{uploading=false;}}
function vendorView(){main.innerHTML=pageHead('廠商與攤位','攤位號取自事前資料；標為待確認者需再核對本屆官方名單。')+`<div class="vendor-list">${vendors.map(v=>{const rs=records.filter(r=>r.vendor===v.name&&!r.archived);return `<section class="vendor-card"><header><h2>${vendorBadge(v.name)}</h2><span class="booth">${v.booth?'#'+esc(v.booth):'待補'}</span></header><p>${esc(v.event||'G2E 2026')} · ${esc(v.boothStatus||'待確認')}<br>${esc(v.boothSource||'無來源')}${v.verifiedAt?' · '+esc(v.verifiedAt):''}</p><p>${rs.length}筆資料 · ${rs.filter(r=>r.seen).length}筆已看 · ${rs.filter(r=>r.priority==='必看').length}筆必看</p><div class="actions"><button data-action="vendor-filter" data-vendor="${esc(v.name)}">查看機台</button><button data-action="vendor-new" data-vendor="${esc(v.name)}">＋ 新機台</button></div><details><summary>編輯攤位與備註</summary><form class="vendor-form" data-id="${esc(v.id)}"><div class="form-grid"><div class="form-field wide"><label>攤位編號<input name="booth" value="${esc(v.booth)}"></label></div><div class="form-field wide"><label>資料來源<input name="boothSource" value="${esc(v.boothSource)}" placeholder="官方網址或查證說明"></label></div><div class="form-field wide"><label>確認狀態<select name="boothStatus">${options(['待官方核對','已確認','待確認'],v.boothStatus)}</select></label></div><div class="form-field wide"><label>確認日期<input type="date" name="verifiedAt" value="${esc(v.verifiedAt)}"></label></div><div class="form-field wide"><label>備註<textarea name="note">${esc(v.note)}</textarea></label></div><button type="submit">儲存攤位</button></div></form></details></section>`;}).join('')}</div>`;}
async function notesView(token){const drafts=await DB.all('drafts');if(token!==routeToken)return;const mine=records.filter(r=>hasFieldRecord(r)&&!r.archived).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));main.innerHTML=pageHead('我的紀錄','這支手機的筆記與照片。單機資料不會自動與同事同步。',`<button data-nav="settings">備份資料</button>`)+`${drafts.length?`<section class="panel"><h2>尚未完成的草稿</h2>${drafts.map(d=>`<p><a href="#${d.id.startsWith('casino-')?'casino-edit/'+encodeURIComponent(d.id.slice(7)):d.id==='new'?'new':d.id.startsWith('edit-')?'edit/'+encodeURIComponent(d.id.slice(5)):'game/'+encodeURIComponent(d.id.slice(5))}">${esc(d.record?.name|| (d.id.startsWith('casino-')?'賭場觀察草稿':d.id.startsWith('note-')?'現場筆記草稿':'新機台草稿'))}</a> <small>${esc(fmt(d.savedAt))}</small></p>`).join('')}</section>`:''}<div class="resultbar">${mine.length}筆現場紀錄</div>${mine.length?`<div class="timeline">${mine.map(r=>`<article class="timeline-item"><small>${esc(fmt(r.updatedAt))} · ${esc(r.vendor)} · ${esc(r.location)}</small><h2><a href="#game/${encodeURIComponent(r.id)}">${esc(r.name)}</a></h2><p>${esc(r.notes.at(-1)?.text||r.description.slice(0,180)||'已更新資料')}</p><small>${r.mediaIds.length}張圖片 · ${r.notes.length}筆觀察</small></article>`).join('')}</div>`:'<div class="empty"><h2>準備好第一筆現場紀錄了嗎？</h2><p>先拍照，再補名稱與玩法。</p><a class="file-button" href="#new">＋ 新增機台</a></div>'}`;}
async function swMessage(type,onProgress){const reg=await navigator.serviceWorker.ready;const worker=reg.active;return new Promise((resolve,reject)=>{const channel=new MessageChannel();let timer=setTimeout(()=>{channel.port1.close();reject(Error('離線下載回應逾時，請留在前景並重試。'));},type==='PREPARE'?180000:15000);channel.port1.onmessage=e=>{const data=e.data;if(onProgress)onProgress(data);if(data.error||data.ready!==undefined){clearTimeout(timer);channel.port1.close();data.error?reject(Error(data.error)):resolve(data);}};worker.postMessage({type},[channel.port2]);});}
async function settings(token){const drafts=await DB.all('drafts');const meta=await DB.get('meta','lastBackup');let estimate={};try{estimate=await navigator.storage?.estimate()||{};}catch{}if(token!==routeToken)return;const archived=records.filter(r=>r.archived);main.innerHTML=pageHead('資料與備份','資料保存在目前網址、目前瀏覽器／主畫面App的本機儲存空間。')+updatePanel()+`<div class="notice">請固定使用加入主畫面的版本記錄。切換網址、瀏覽器或清除網站資料，可能看不到原本的資料；先匯出完整備份，再搬到新位置。</div><div class="setting-grid"><section class="panel"><h2>離線資料</h2><p id="offline-status">${offlineReady?'App 已備妥離線使用；私人資料從本機資料庫讀取。':'尚未確認完整離線資料，請連網下載一次。'}</p><p class="muted">只下載公開 App 頁面與程式。匯入的照片、詞彙與筆記已存本機，不從 GitHub 下載，也不會傳回 GitHub。</p><div class="progress"><span id="offline-progress"></span></div><div class="actions"><button class="primary" data-action="offline" ${heavy?'disabled':''}>${offlineReady?'檢查離線資料':'下載離線資料'}</button><button data-action="persist">請求保留本機資料</button></div><p id="persist-status" class="muted">瀏覽器不一定核准保留，仍需自行備份。</p></section><section class="panel"><h2>私人資料匯入與備份</h2><p>完整備份包含機台、賭場觀察、筆記、廠商、已匯入詞彙及已引用照片／錄音原檔。匯出成一個JSON檔，可存到iPhone「檔案」。</p><p class="muted">草稿共 ${drafts.length} 份：請先儲存成正式紀錄，草稿不納入備份。私人資料包中的圖片匯入後即可離線備份。</p><div class="form-field"><label for="backup-scope">備份範圍</label><select id="backup-scope"><option value="all">全部資料（完整備份）</option><option value="mine">本機新增／修改的資料（含賭場）</option><option value="casinos">所有賭場觀察</option><optgroup label="按賭場分批">${casinos.map(c=>`<option value="casino:${esc(c.id)}">${esc(c.name)}</option>`).join('')}</optgroup><optgroup label="按廠商分批">${vendors.map(v=>`<option value="vendor:${esc(v.name)}">${esc(v.name)}</option>`).join('')}</optgroup><optgroup label="按機台分批">${records.map(r=>`<option value="record:${esc(r.id)}">${esc(r.name)}</option>`).join('')}</optgroup></select><small>大量照片可分批；按機台／廠商分批不含賭場，請另外匯出賭場觀察。</small></div><div class="actions" style="margin-top:12px"><button class="primary" data-action="backup" ${heavy?'disabled':''}>製作完整備份</button><label class="file-button">選擇私人資料包／備份<input id="restore-input" type="file" accept=".json,application/json"></label></div><div id="backup-output"></div><p class="muted">上次製作備份：${meta?esc(fmt(meta.value)):'尚未製作'}。請另行確認檔案確實存好。</p><p id="backup-status" role="status"></p><div id="restore-preview"></div></section><section class="panel"><h2>文字表與容量</h2><p>${records.filter(r=>!r.archived).length}筆機台 · ${casinos.length} 筆賭場 · ${[...media.values()].filter(m=>!m.type?.startsWith('audio/')).length}個圖片索引 · ${[...media.values()].filter(m=>m.type?.startsWith('audio/')).length}個錄音索引</p><p class="muted">瀏覽器回報使用約 ${estimate.usage?Math.round(estimate.usage/1024/1024)+' MB':'未知'}。此數字可能包括離線快取。</p><button data-action="csv-all">匯出全部 CSV 文字表</button><p class="muted">CSV沒有圖片原檔，不能代替完整備份。匯出包可交給同事或AI整理；本App不會自動傳到聊天。</p></section><section class="panel"><h2>iPhone 安裝與使用</h2><p><a href="#help">閱讀完整使用教學（v2.2）</a></p><p class="install-state">${matchMedia('(display-mode: standalone)').matches||navigator.standalone?'✓ 已從主畫面 App 開啟':'目前從瀏覽器開啟；加入主畫面後，固定從圖示記錄。'}</p><ol><li>以 iPhone Safari 開啟部署後的固定 HTTPS 網址。</li><li>開啟分享選單 → 加入主畫面，之後固定從圖示開啟。</li><li>先下載離線資料，再開飛航模式試寫一筆。</li><li>每天收工製作完整備份，存到「檔案」。</li></ol><p class="muted">首次安裝與 App 離線準備需要網路；資料包須另存到手機「檔案」。此版本不會同步資料到 GitHub。</p></section></div><section class="panel" style="margin-top:22px"><h2>封存資料（${archived.length}）</h2>${archived.map(r=>`<p>${esc(r.name)} <button class="compact" data-action="unarchive" data-id="${esc(r.id)}">還原</button></p>`).join('')||'<p class="muted">沒有封存資料。</p>'}</section>`;if('serviceWorker'in navigator&&isSecureContext)swMessage('STATUS').then(s=>{offlineReady=s.ready;if($('#offline-status'))$('#offline-status').textContent=s.ready?'App 已備妥離線使用；私人資料從本機資料庫讀取。':'尚未完成 App 離線準備。';}).catch(()=>{});}
async function loadBlob(m){if(m.blob)return m.blob;if(!/^assets\/[\w.-]+$/.test(m.path||''))throw Error('找不到圖片 '+m.name);const response=await fetch(m.path);if(!response.ok)throw Error('無法讀取 '+m.name+'；請連網或先下載離線資料。');return response.blob();}
const toData=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});
function dataBlob(data){const [head,payload]=data.split(',');const type=head.slice(5).split(';')[0];const bytes=Uint8Array.from(atob(payload),c=>c.charCodeAt(0));return new Blob([bytes],{type});}
function saveDownload(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function makeBackup(){if(heavy)return;heavy=true;try{const drafts=await DB.all('drafts');if(drafts.length)throw Error('還有 '+drafts.length+' 份草稿。請先到「我的紀錄」儲存，或放棄草稿後再備份。');const scope=$('#backup-scope')?.value||'all';const casinoSelection=scope==='all'||scope==='mine'||scope==='casinos'?casinos:scope.startsWith('casino:')?casinos.filter(c=>c.id===scope.slice(7)):[];const selection=scope==='casinos'||scope.startsWith('casino:')?[]:scope==='all'?records:scope==='mine'?records.filter(r=>r.userEdited):scope.startsWith('vendor:')?records.filter(r=>r.vendor===scope.slice(7)):records.filter(r=>r.id===scope.slice(7));if(!selection.length&&!casinoSelection.length)throw Error('這個範圍沒有可備份的資料。');const snapshot=structuredClone(selection), vs=structuredClone(vendors);const mids=[...new Set([...snapshot,...casinoSelection].flatMap(r=>[...r.mediaIds,...(r.audioIds||[])]))];const estimated=mids.reduce((sum,mid)=>sum+(media.get(mid)?.size||media.get(mid)?.blob?.size||0),0);if(estimated>200*1024*1024)throw Error('附件總量超過200 MB，請用備份範圍選單按廠商或機台分批，避免手機記憶體不足。');const packed=[];for(let i=0;i<mids.length;i++){if($('#backup-status'))$('#backup-status').textContent=`打包附件 ${i+1} / ${mids.length}…`;const m=media.get(mids[i]);if(!m)throw Error('備份缺少附件 '+mids[i]);packed.push({id:m.id,name:m.name,type:m.type,caption:m.caption||'',origin:m.origin||'',createdAt:m.createdAt||'',data:await toData(await loadBlob(m))});}const b={format:'g2e-field-notes',schema:SCHEMA,scope,exportedAt:now(),glossary:EKG.terms.length?structuredClone(EKG):undefined,records:snapshot,casinos:structuredClone(casinoSelection),vendors:vs,media:packed};checkBackup(b);const blob=new Blob([JSON.stringify(b)],{type:'application/json'});preparedBackup={blob,name:'G2E'+(scope==='all'?'完整':'分批')+'備份-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json'};await DB.put('meta',{id:'lastBackup',value:now()});if($('#backup-output'))$('#backup-output').innerHTML=`<p class="notice good">已製作 ${snapshot.length} 筆機台、${casinoSelection.length} 筆賭場、${packed.filter(m=>!m.type?.startsWith('audio/')).length} 張原圖、${packed.filter(m=>m.type?.startsWith('audio/')).length} 段錄音（${(blob.size/1024/1024).toFixed(1)} MB）。請按下方按鈕存檔。</p><div class="actions"><button data-action="download-backup">下載備份檔</button><button data-action="share-backup">分享／存到檔案</button></div>`;if($('#backup-status'))$('#backup-status').textContent='備份製作完成；尚需下載或存到檔案。';}finally{heavy=false;}}
async function previewRestore(file){if(heavy||!file)return;if(file.size>350*1024*1024)throw Error('這份備份超過350 MB，請在電腦版處理或減少分批資料量。');const b=checkBackup(JSON.parse(await file.text()));if(b.glossary)checkVocabulary(b.glossary);if(!EKG.terms.length&&!b.glossary&&b.records.some(r=>r.tags?.length))throw Error('這份舊備份沒有詞彙表。請先匯入新版私人資料包，再還原。');if(b.glossary&&EKG.terms.length&&JSON.stringify(b.glossary.terms)!==JSON.stringify(EKG.terms))throw Error('詞彙版本不同，為避免覆蓋請先保留雙方資料包，另行核對。');const merge=mergeRecords(records,b.records);const cm=mergeRecords(casinos,b.casinos||[]);pendingImport=b;$('#restore-preview').innerHTML=`<p class="notice">資料包／備份含 ${b.records.length} 筆機台、${b.casinos?.length||0} 筆賭場、${b.media.filter(m=>!m.data.startsWith('data:audio/')).length} 張圖片、${b.media.filter(m=>m.data.startsWith('data:audio/')).length} 段錄音、${b.glossary?.terms.length||0} 項詞彙。將新增 ${merge.added} 筆、以較新時間更新 ${merge.updated} 筆；賭場新增 ${cm.added} 筆、更新 ${cm.updated} 筆。本機較新資料保留；賭場同樣依編號合併、較新時間優先，舊備份不會清除現有賭場。不是多人無損合併。此操作會寫入本機資料庫。</p><button data-action="restore" class="primary">確認合併還原</button><button data-action="cancel-restore">取消</button>`;}
async function restore(){if(!pendingImport||heavy)return;heavy=true;try{const b=pendingImport;const cm=mergeRecords(casinos,b.casinos||[]);const merge=mergeRecords(records,b.records);const changes=merge.records.map(value=>({store:'records',value}));for(const m of b.media){if(media.get(m.id)?.blob)continue;const blob=dataBlob(m.data);changes.push({store:'media',value:{id:m.id,name:m.name,type:blob.type,size:blob.size,caption:m.caption,origin:m.origin,createdAt:m.createdAt,blob,thumbBlob:blob.type.startsWith('audio/')?null:await thumb(blob)}});}for(const v of b.vendors){const old=vendors.find(x=>x.id===v.id);if(!old||Date.parse(v.updatedAt||'')>Date.parse(old.updatedAt||''))changes.push({store:'vendors',value:v});}if(b.casinos)changes.push({store:'meta',value:{id:'casinos',value:mergeRecords(casinos,b.casinos).records}});if(b.glossary)changes.push({store:'meta',value:{id:'glossary',value:b.glossary}});await DB.batch(changes);if(b.glossary)setVocabulary(b.glossary);pendingImport=null;for(const u of objectUrls.values())URL.revokeObjectURL(u);objectUrls.clear();await refresh();heavy=false;await settings(routeToken);notify(`還原完成：機台新增${merge.added}、更新${merge.updated}；賭場新增${cm.added}、更新${cm.updated}。`);}finally{heavy=false;}}
async function imageViewer(mid){const m=media.get(mid);if(!m)return;const url=imageUrl(mid);$('#viewerImage').src=url;$('#viewerImage').alt=m.caption||m.name;const rid=decodeURIComponent(location.hash.split('/')[1]||'');const caption=(editor?.record||records.find(r=>r.id===rid)||casinos.find(r=>r.id===rid))?.mediaCaptions?.[mid]||m.caption||'';$('#viewerCaption').textContent=m.name+' · '+mediaOrigin(mid)+(caption?' · '+caption:'');$('#downloadImage').href=url;$('#downloadImage').download=m.name;$('#viewer').showModal();}
async function route(){if(uploading||heavy||recorder.active||recorder.recovery){notify('請先完成錄音、附件保存或備份操作。');return;}const token=++routeToken;try{if(editor){await flushDraft();editor=null;}await persistNote();const hash=location.hash.slice(1)||'catalog';const [view,arg]=hash.split('/');document.querySelectorAll('[data-tab]').forEach(a=>{a.classList.toggle('active',a.dataset.tab===(view.startsWith('casino')?'casinos':view==='game'||view==='edit'?'catalog':view));if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(view==='casinos')casinoList();else if(view==='casino')casinoDetail(decodeURIComponent(arg||''));else if(view==='casino-edit')await casinoEdit(decodeURIComponent(arg||'new'),token);else if(view==='help')main.innerHTML=helpView();else if(view==='catalog')catalog();else if(view==='game')detail(decodeURIComponent(arg||''));else if(view==='edit')await edit(decodeURIComponent(arg||''),token);else if(view==='new')await edit('',token);else if(view==='glossary')glossary();else if(view==='vendors')vendorView();else if(view==='notes')await notesView(token);else if(view==='settings')await settings(token);else catalog();window.scrollTo(0,0);}catch(err){notify(errorText(err));if(!editor)main.innerHTML=pageHead('無法開啟這頁',esc(errorText(err)))+'<a href="#catalog">返回圖鑑</a>';}}
async function persistNote(){const f=$('#note-form');if(!f)return;const text=f.elements.text.value;const key='note-'+f.dataset.id;if(!text.trim())return;await DB.put('drafts',{id:key,text,noteId:f.dataset.noteId||'',location:f.elements.location.value,locationDetail:f.elements.locationDetail.value,savedAt:now()});if($('#note-draft-status'))$('#note-draft-status').textContent='筆記草稿已存本機';}
document.addEventListener('input',e=>{if(e.target.id==='ekg-query'){renderGlossary();return;}if(e.target.id==='ekg-picker-search'){renderEKGPicker();return;}if(e.target.id==='search'){filters.q=e.target.value;renderResults();return;}if(e.target.closest('#edit-form,#casino-form')){if(e.target.dataset.caption&&editor){editor.record.mediaCaptions||={};editor.record.mediaCaptions[e.target.dataset.caption]=e.target.value;}clearTimeout(formTimer);formTimer=setTimeout(()=>queueDraft(),250);}if(e.target.closest('#note-form'))persistNote().catch(err=>notify(errorText(err)));});
document.addEventListener('change',async e=>{try{if(e.target.id.startsWith('filter-')){const k=e.target.id.slice(7);filters[k]=k==='state'?({'必看':'star','未看':'unseen','已看':'seen','有現場紀錄':'edited','待補圖':'missing'})[e.target.value]||'':e.target.value;renderResults();}if(['photo-input','camera-input'].includes(e.target.id))await addPhotos([...e.target.files]);if(e.target.id==='audio-input'){if(uploading)throw Error('請先完成目前的錄音或檔案處理。');uploading=true;try{for(const file of e.target.files)await attachAudio(file);audioStatus('錄音已存草稿，請儲存紀錄。');}finally{uploading=false;e.target.value='';}}if(e.target.id==='restore-input')await previewRestore(e.target.files[0]);if(e.target.closest('#edit-form,#casino-form')&&!e.target.files)queueDraft();}catch(err){notify(errorText(err));if($('#form-error'))$('#form-error').textContent=errorText(err);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;try{if(recorder.active||recorder.recovery)throw Error('請先停止並保存錄音。');if(form.id==='casino-form'){if(uploading||heavy)throw Error('照片仍在處理，請稍候。');await flushDraft();const c={...structuredClone(editor.record),name:editor.record.name.trim(),updatedAt:now()};validateCasino(c);await DB.batch([{store:'meta',value:{id:'casinos',value:mergeRecords(casinos,[c]).records}},{store:'meta',value:{id:'currentContext',value:{location:'賭場',locationDetail:c.name}}},{store:'drafts',delete:true,id:editor.key}]);editor=null;await refresh();notify('賭場觀察與照片已存本機');location.hash='casino/'+encodeURIComponent(c.id);}else if(form.id==='edit-form'){if(uploading||heavy)throw Error('照片仍在處理，請稍候。');await flushDraft();readForm();const r=structuredClone(editor.record);r.name=r.name.trim()||'名稱待確認';r.vendor=r.vendor.trim()||'廠商待確認';r.tags=tokens(r.tags);if(r.tags.some(t=>!termByName.has(t)))throw Error('請從 EKG 清單挑選玩法標籤。');r.updatedAt=now();r.userEdited=true;validateRecord(r);if(!editor.originalId&&!r.description&&!r.mediaIds.length&&!(r.audioIds||[]).length&&r.name==='名稱待確認')throw Error('請先填名稱、說明，或加入照片／錄音。');const changes=[{store:'records',value:r},{store:'drafts',delete:true,id:editor.key}];if(!vendors.some(v=>v.name===r.vendor))changes.push({store:'vendors',value:{id:r.vendor,name:r.vendor,event:'G2E 2026',booth:'',boothStatus:'待確認',boothSource:'',verifiedAt:'',note:''}});changes.push({store:'meta',value:{id:'currentContext',value:{location:r.location,locationDetail:r.locationDetail}}});await DB.batch(changes);editor=null;await refresh();notify('紀錄與附件已存本機');location.hash='game/'+encodeURIComponent(r.id);}else if(form.id==='note-form'){const r=currentRecord(form.dataset.id),fd=new FormData(form),text=String(fd.get('text')).trim();if(!text)throw Error('請先輸入筆記。');const prior=r.notes.find(n=>n.id===form.dataset.noteId);const note={id:prior?.id||id(),text,createdAt:prior?.createdAt||now(),updatedAt:now(),location:String(fd.get('location')),locationDetail:String(fd.get('locationDetail')).trim()};await DB.batch([{store:'records',value:{...r,notes:prior?r.notes.map(n=>n.id===prior.id?note:n):[...r.notes,note],location:note.location,locationDetail:note.locationDetail,seen:true,userEdited:true,updatedAt:now()}},{store:'drafts',delete:true,id:'note-'+r.id}]);form.elements.text.value='';await refresh();detail(r.id);notify('現場筆記已存本機');}else if(form.classList.contains('vendor-form')){const v=vendors.find(v=>v.id===form.dataset.id),fd=new FormData(form),next={...v,updatedAt:now()};for(const k of ['booth','boothSource','boothStatus','verifiedAt','note'])next[k]=String(fd.get(k)||'').trim();if(next.boothStatus==='已確認'&&(!next.booth||!next.boothSource||!next.verifiedAt))throw Error('標示已確認前，請補攤位、來源與確認日期。');await DB.put('vendors',next);await refresh();notify('攤位資料已存本機');}}catch(err){notify(errorText(err));if($('#form-error'))$('#form-error').textContent=errorText(err);}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]'),nav=e.target.closest('[data-nav]');if((uploading||heavy||recorder.recovery)&&e.target.closest('a,button,label')){if(!['record-stop','audio-retry','audio-rescue','audio-discard'].includes(button?.dataset.action)){e.preventDefault();notify('請等待目前操作完成。');return;}}try{if(nav){location.hash=nav.dataset.nav;return;}if(!button)return;const {action,id:rid,mid}=button.dataset;
 if(action==='check-update'){await checkUpdate();return;}
 else if(action==='apply-update'){if(!updateAvailable)return;if(editor)await flushDraft();await persistNote();if(!confirm('已儲存目前草稿。套用新版會重新開啟 App，不會清除資料；請確認重要內容已備份。'))return;location.reload();return;}
 else if(action==='remember-location'){readForm();await rememberContext(editor.record.location,editor.record.locationDetail);$('#context-status').textContent=' 已記住：'+currentContext.location+' '+currentContext.locationDetail;return;}
 else if(action==='clear-location'){await rememberContext('展場','');$('#context-status').textContent=' 已清除；下筆新紀錄回到展場空白地點。';return;}
 else if(action==='quick-toggle'){readForm();editor.quick=!editor.quick;await queueDraft();editView();return;}
 else if(action==='record-start'){await recorder.start();return;}
 else if(action==='record-stop'){await recorder.stop();return;}
 else if(action==='audio-retry'){await recorder.retry();return;}
 else if(action==='audio-rescue'){if(recorder.recovery)saveDownload(recorder.recovery,recorder.recovery.name);return;}
 else if(action==='audio-discard'){if(confirm('這段錄音尚未保存；請先下載留存。確定放棄暫存錄音？'))recorder.discard();return;}
 else if(action==='remove-audio'){editor.record.audioIds=(editor.record.audioIds||[]).filter(x=>x!==mid);await queueDraft();$('#audio-list').innerHTML=audioList(editor.record,true);return;}
 else if(action==='close-term'){$('#term-dialog').close();return;}
 else if(action==='term'){showTerm(button.dataset.term);return;}
 else if(action==='ekg-toggle'){const t=termById.get(button.dataset.term);if(!t||!editor)return;readForm();editor.record.tags=editor.record.tags.includes(t.term_en)?editor.record.tags.filter(x=>x!==t.term_en):[...editor.record.tags,t.term_en];await queueDraft();renderEKGPicker();return;}
 else if(action==='reset-filter'){Object.keys(filters).forEach(k=>filters[k]='');catalog();}
 else if(action==='edit')location.hash='edit/'+encodeURIComponent(rid);
 else if(action==='seen'||action==='star'){const r=currentRecord(rid);await saveRecord({...r,...(action==='seen'?{seen:!r.seen}:{priority:r.priority==='必看'?'值得看':'必看'})});if($('#results'))renderResults();else detail(rid);notify(action==='seen'?'參觀狀態已儲存':'關注程度已儲存');}
 else if(action==='vendor-filter'){filters.vendor=button.dataset.vendor;location.hash='catalog';}
 else if(action==='vendor-new'){filters.vendor=button.dataset.vendor;location.hash='new';}
 
 else if(action==='remove-media'){editor.record.mediaIds=editor.record.mediaIds.filter(x=>x!==mid);await queueDraft();renderUploads();}
 else if(action==='leave-edit'){await flushDraft();location.hash='notes';}
 else if(action==='discard-draft'){if(!confirm('放棄這份未儲存的草稿？已正式儲存的資料不受影響。'))return;clearTimeout(formTimer);await draftQueue;await DB.batch([{store:'drafts',delete:true,id:editor.key}]);editor=null;location.hash='notes';}
 else if(action==='archive'){if(!confirm('封存此筆資料？之後可在「資料與備份」還原。'))return;clearTimeout(formTimer);await draftQueue;await saveRecord({...currentRecord(rid),archived:true});await DB.batch([{store:'drafts',delete:true,id:editor.key}]);editor=null;location.hash='catalog';}
 else if(action==='unarchive'){await saveRecord({...currentRecord(rid),archived:false});await settings(routeToken);notify('已還原資料');}
 else if(action==='image')await imageViewer(mid);
 else if(action==='edit-note'){const n=currentRecord(rid).notes.find(n=>n.id===button.dataset.noteId);const f=$('#note-form');if(f.elements.text.value.trim()&&!confirm('以選取的筆記取代目前輸入草稿？'))return;f.dataset.noteId=n.id;f.elements.text.value=n.text;f.elements.location.value=n.location||'展場';f.elements.locationDetail.value=n.locationDetail||'';f.querySelector('button[type=submit]').textContent='儲存筆記修改';await persistNote();f.scrollIntoView({block:'center'});f.elements.text.focus();}
 else if(action==='jump-note'){$('#note-section').scrollIntoView({block:'start'});$('#note-form textarea').focus();}
 else if(action==='csv'||action==='csv-all')saveDownload(new Blob([csv(action==='csv'?filtered():records.filter(r=>!r.archived))],{type:'text/csv;charset=utf-8'}),'G2E機台資料.csv');
 else if(action==='offline'){if(!('serviceWorker'in navigator)||!isSecureContext)throw Error('離線功能需使用HTTPS網址或電腦localhost，不能直接開file檔案。');heavy=true;try{await swMessage('PREPARE',p=>{if($('#offline-status'))$('#offline-status').textContent=p.error?p.error:p.ready?'離線資料下載完成':`下載 ${p.done||0} / ${p.total||'?'} 個檔案…`;if($('#offline-progress')&&p.total)$('#offline-progress').style.width=(100*p.done/p.total)+'%';});offlineReady=true;notify('離線資料已就緒');}finally{heavy=false;}}
 else if(action==='persist'){const ok=await navigator.storage?.persist?.();$('#persist-status').textContent=ok?'瀏覽器已允許保留儲存空間；仍建議每日備份。':'瀏覽器未核准或不支援保留請求；請每天匯出備份。';}
 else if(action==='backup')await makeBackup();
 else if(action==='download-backup'&&preparedBackup)saveDownload(preparedBackup.blob,preparedBackup.name);
 else if(action==='share-backup'&&preparedBackup){const file=new File([preparedBackup.blob],preparedBackup.name,{type:'application/json'});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'G2E展場備份'});else{saveDownload(preparedBackup.blob,preparedBackup.name);notify('此瀏覽器不支援檔案分享，已改用下載。');}}
 else if(action==='restore')await restore();
 else if(action==='cancel-restore'){pendingImport=null;$('#restore-preview').innerHTML='';}
 }catch(err){notify(errorText(err));if($('#backup-status'))$('#backup-status').textContent=errorText(err);}});
document.addEventListener('click',e=>{if(e.target.matches('[data-image]')&&!e.target.closest('a.cover,[data-action]')){const mid=e.target.dataset.image;imageViewer(mid).catch(err=>notify(errorText(err)));}});
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){e.target.alt='圖片未下載或此裝置無法預覽；可連網重試或下載原檔。';}},true);
$('#closeViewer').onclick=()=>$('#viewer').close();$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer'))$('#viewer').close();});
window.addEventListener('hashchange',route);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){if(recorder.active)recorder.stop();if(editor)queueDraft();persistNote().catch(()=>{});}});
window.addEventListener('beforeunload',e=>{if(uploading||heavy||draftError||recorder.active||recorder.recovery){e.preventDefault();e.returnValue='';}});
async function start(){try{if(location.protocol==='file:'){main.innerHTML=pageHead('請用本機伺服器或HTTPS開啟','這個App需要本機資料庫與離線快取，不能直接雙擊HTML使用。')+'<p>請依 README 的啟動指令開啟。原本的單檔圖文表仍可直接開啟。</p>';return;}await DB.openDB();const vocabulary=await DB.get('meta','glossary');if(vocabulary)setVocabulary(vocabulary.value);await refresh();$('#storageStatus').textContent='本機保存 · 備份';if('serviceWorker'in navigator&&isSecureContext)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(err=>notify('離線快取尚未啟用：'+errorText(err)));await route();}catch(err){main.innerHTML=pageHead('資料庫尚未開啟',esc(errorText(err)))+'<p>請使用一般瀏覽模式，確認儲存空間與網站資料權限，再重新開啟。</p>';}}
start();

function casinoList(){
 main.innerHTML=pageHead('賭場觀察','記下每間賭場的環境、機台配置與現場特色；與遊戲圖鑑分開保存。','<a class="file-button primary" href="#casino-edit/new">＋ 新增賭場</a>')+'<p><a href="#help">使用教學與備份說明</a></p><div class="search"><input id="casino-search" type="search" aria-label="搜尋賭場" placeholder="搜尋賭場名稱、城市或觀察內容"></div><div id="casino-results"></div>';
 renderCasinos('');$('#casino-search').addEventListener('input',e=>renderCasinos(e.target.value));
}
function renderCasinos(query){const q=query.trim().toLowerCase();const list=casinos.filter(c=>[c.name,c.city,c.description].join(' ').toLowerCase().includes(q)).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));$('#casino-results').innerHTML=`<p class="muted">${list.length} 筆賭場觀察</p>`+(list.length?'<div class="catalog">'+list.map(c=>`<article class="game"><a class="cover" href="#casino/${encodeURIComponent(c.id)}" aria-label="查看 ${esc(c.name)}">${cover(c)}</a><div class="game-body"><h2><a href="#casino/${encodeURIComponent(c.id)}">${esc(c.name)}</a></h2><p class="muted">${esc(c.city||'城市未填')} · ${esc(c.visitedOn||'日期未填')}</p><p class="casino-copy">${esc(c.description.slice(0,120)||'尚未填寫觀察')}</p><a class="file-button" href="#casino-edit/${encodeURIComponent(c.id)}">編輯觀察</a></div></article>`).join('')+'</div>':'<section class="empty"><h2>先記下第一間賭場</h2><p>名稱必填；照片與文字可以晚點補。不確定的內容請註明待確認。</p><a class="file-button" href="#casino-edit/new">＋ 新增賭場</a></section>');}
function casinoDetail(cid){const c=casinos.find(c=>c.id===cid);if(!c)throw Error('找不到這筆賭場觀察。');main.innerHTML='<a class="back" href="#casinos">‹ 返回賭場觀察</a>'+pageHead(c.name,`${esc(c.city||'城市未填')} · ${esc(c.visitedOn||'日期未填')}`,`<a class="file-button primary" href="#casino-edit/${encodeURIComponent(c.id)}">編輯觀察</a>`)+`<section class="panel"><h2>特性與觀察</h2><p class="casino-copy">${esc(c.description||'尚未填寫')}</p><p class="muted">最後更新：${esc(fmt(c.updatedAt))}。這是自行記錄的觀察，不是官方資料。</p></section><section class="panel"><h2>照片（${c.mediaIds.length}）</h2><div class="uploads">${c.mediaIds.map(mid=>`<div class="upload"><button data-action="image" data-mid="${esc(mid)}" aria-label="放大賭場照片">${image(mid)}</button>${photoLabel(mid)}<p>${esc(c.mediaCaptions?.[mid]||media.get(mid)?.name||'')}</p></div>`).join('')||'<p>尚未加入照片。</p>'}</div><p class="muted">拍攝前請確認現場規定，避免拍到可辨識的其他訪客。</p></section>`+'<section class="panel"><h2>錄音附件</h2>'+audioList(c)+'</section>';}
async function casinoEdit(cid,token){const key='casino-'+cid;const draft=await DB.get('drafts',key);if(token!==routeToken)return;const prior=casinos.find(c=>c.id===cid);if(cid!=='new'&&!prior&&!draft)throw Error('找不到這筆賭場觀察。');const record=structuredClone(draft?.record||prior||{id:'CASINO-'+id(),name:'',city:'',visitedOn:'',description:'',mediaIds:[],mediaCaptions:{},createdAt:now(),updatedAt:now()});editor={casino:true,key,record,originalId:prior?.id||'',draftRestored:!!draft};editView();}
function casinoEditView(){const c=editor.record;main.innerHTML=pageHead(editor.originalId?'編輯賭場觀察':'新增賭場觀察',editor.draftRestored?'已恢復本機草稿，請完成後按儲存。':'只需先填名稱，觀察與照片可之後補。')+`<form id="casino-form" class="edit-form"><section class="panel"><div class="form-grid"><div class="form-field wide"><label for="casino-name">賭場名稱（必填）</label><input id="casino-name" name="name" value="${esc(c.name)}" required placeholder="輸入賭場名稱"></div><div class="form-field"><label for="casino-city">城市／區域（選填）</label><input id="casino-city" name="city" value="${esc(c.city)}"></div><div class="form-field"><label for="casino-date">觀察日期（選填）</label><input id="casino-date" type="date" name="visitedOn" value="${esc(c.visitedOn)}"></div><div class="form-field wide"><label for="casino-description">特性與文字說明</label><textarea id="casino-description" class="long" name="description" placeholder="例如：整體環境、機台廠商與配置、熱門區域、玩家觀察、值得回訪的特色。可用 iPhone 鍵盤麥克風說話輸入。">${esc(c.description)}</textarea><small>觀察與推測請分開；不必現場填完所有內容。</small></div></div></section><section class="panel"><h2>賭場照片</h2><p class="muted">只存本機，單張上限 25 MB；可拍照或從相簿選取。請遵守現場拍攝規定。</p><div class="actions"><label class="file-button">拍照<input type="file" id="camera-input" accept="image/*" capture="environment"></label><label class="file-button">從相簿加入<input type="file" id="photo-input" accept="image/*" multiple></label><small id="upload-status"></small></div><div id="uploads" class="uploads"></div></section><div class="form-footer"><small id="draft-status">${editor.draftRestored?'已恢復草稿':'輸入後自動存草稿'}</small><button type="button" data-action="leave-edit">稍後繼續</button><button type="submit" class="primary">儲存賭場觀察</button></div><p id="form-error" class="save-error" role="alert"></p><button type="button" class="quiet" data-action="discard-draft">放棄這份草稿</button></form>`;renderUploads();mountAudio();}

function audioList(r,editable=false){return (r.audioIds||[]).map(aid=>{const m=media.get(aid);if(!m)return '<p>找不到錄音附件，請檢查備份。</p>';return `<div class="audio-item"><p>${esc(m.name)} <small>${(m.size/1024/1024).toFixed(1)} MB · 自行加入</small></p><audio controls preload="metadata" src="${esc(imageUrl(aid))}">此瀏覽器不支援播放</audio><div class="actions"><a class="file-button" download="${esc(m.name)}" href="${esc(imageUrl(aid))}">下載音檔</a>${editable?`<button type="button" data-action="remove-audio" data-mid="${esc(aid)}">從這筆移除</button>`:''}</div></div>`;}).join('')||'<p class="muted">尚未加入錄音。</p>';}
function mountAudio(){if(!editor)return;const form=$('#edit-form,#casino-form');if(!form)return;let box=$('#audio-panel');if(!box){box=document.createElement('section');box.id='audio-panel';box.className='panel';form.insertBefore(box,form.querySelector('.form-footer'));}box.innerHTML=`<h2>錄音附件</h2><p class="muted">錄自己的觀察，先確認現場允許。單檔上限 50 MB；只存本機，不會轉逐字稿。</p><div class="actions"><label class="file-button">從檔案加入錄音<input id="audio-input" type="file" accept="audio/*,.m4a,.mp3,.wav,.webm,.ogg,.aac,.flac" multiple></label><button type="button" data-action="record-start">開始錄音（試用）</button><button type="button" data-action="record-stop" disabled>停止並保存</button></div><p id="audio-status" role="status">直接錄音最長 3 分鐘；請勿鎖屏或切換 App，完成後務必試聽。</p><div id="audio-recovery" hidden><button type="button" data-action="audio-retry">重試保存錄音</button><button type="button" data-action="audio-rescue">下載暫存音檔</button><button type="button" data-action="audio-discard">放棄未保存錄音</button></div><div id="audio-list">${audioList(editor.record,true)}</div>`;}
async function attachAudio(file){if(!editor)throw Error('請先開啟要記錄的機台或賭場。');const type=validateAudio(file);readForm();await flushDraft();const m={id:'audio-'+id(),name:file.name,type,size:file.size,origin:'自行加入',createdAt:now(),blob:new Blob([file],{type})};const next={...editor.record,audioIds:[...(editor.record.audioIds||[]),m.id]};await DB.batch([{store:'media',value:m},{store:'drafts',value:{id:editor.key,record:next,savedAt:now()}}]);editor.record=next;media.set(m.id,m);if($('#audio-list'))$('#audio-list').innerHTML=audioList(next,true);}
function audioStatus(text){if($('#audio-status'))$('#audio-status').textContent=text;}
function captureLock(value){uploading=value;const start=$('[data-action="record-start"]'),stop=$('[data-action="record-stop"]');if(start)start.disabled=value;if(stop)stop.disabled=!value;setTimeout(()=>{if($('#audio-recovery'))$('#audio-recovery').hidden=!recorder.recovery;},0);}
const recorder=createRecorder({save:attachAudio,status:audioStatus,lock:captureLock});
function quickLayout(){if(!editor||editor.casino)return;const form=$('#edit-form');if(!form)return;let toggle=$('#quick-toggle');if(!toggle){toggle=document.createElement('button');toggle.id='quick-toggle';toggle.type='button';toggle.dataset.action='quick-toggle';form.before(toggle);}toggle.textContent=editor.quick?'展開完整欄位':'收合成極簡速記';toggle.setAttribute('aria-expanded',String(!editor.quick));form.classList.toggle('quick-mode',!!editor.quick);const fields=form.querySelectorAll('.form-grid .form-field,.form-grid .checkrow');for(const field of fields)field.classList.toggle('quick-extra',!field.querySelector('[name="name"],[name="location"],[name="locationDetail"],[name="description"]'));const panels=form.querySelectorAll(':scope > section');if(panels[2]&&panels[2].id!=='audio-panel')panels[2].classList.add('quick-extra');if(editor.quick){main.querySelector('h1').textContent='極簡速記';main.querySelector('.pagehead p').textContent='先留照片、錄音或一句話，名稱與詳細玩法晚點補。';}let ctx=$('#remember-location');if(!ctx){ctx=document.createElement('div');ctx.id='remember-location';ctx.className='context-tools';ctx.innerHTML='<p class="muted">新紀錄會沿用目前地點；不會修改既有紀錄。</p><button type="button" data-action="remember-location">將這裡設為目前地點</button><button type="button" data-action="clear-location">清除記住的地點</button><span id="context-status" role="status"></span>';$('#locationDetail').closest('.form-field').append(ctx);}}
async function rememberContext(location,detail){if(!LOCATIONS.includes(location))return;currentContext={location,locationDetail:detail.trim()};await DB.put('meta',{id:'currentContext',value:currentContext});}
function updatePanel(){return `<section class="panel"><h2>App 版本與更新</h2><p>目前版本：<strong>v${APP_VERSION}</strong></p><button data-action="check-update">檢查更新</button><button data-action="apply-update" hidden id="apply-update">套用新版並重新開啟</button><p id="update-status" role="status">檢查需要網路；不會刪除本機資料。更新前先備份。</p><p class="muted">本次新增極簡速記、目前地點與錄音附件。<a href="#help">查看教學</a></p></section>`;}
async function checkUpdate(){if(uploading||heavy||recorder.active||recorder.recovery)throw Error('請先完成錄音或檔案處理。');heavy=true;try{$('#update-status').textContent='正在連線檢查…';const response=await fetch('./version.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('版本資訊暫時無法取得');const latest=await response.json();if(!/^\d+\.\d+\.\d+$/.test(latest.version))throw Error('版本資訊格式不正確');const reg=await navigator.serviceWorker.getRegistration();if(!reg)throw Error('離線程式尚未安裝完成，請稍後重新開啟 App。');await reg.update();if(reg.installing)await new Promise((resolve,reject)=>{const worker=reg.installing;const timer=setTimeout(()=>reject(Error('新版仍在下載，請稍後再檢查。')),20000);worker.addEventListener('statechange',()=>{if(['installed','activated','redundant'].includes(worker.state)){clearTimeout(timer);worker.state==='redundant'?reject(Error('新版下載失敗，請稍後重試。')):resolve();}});});const status=await swMessage('STATUS');const cachedVersion=status.version.replace('public-v','');if(cachedVersion!==APP_VERSION&&cachedVersion===latest.version){updateAvailable=true;$('#apply-update').hidden=false;$('#update-status').textContent='v'+latest.version+' 已下載。儲存內容後可套用，資料不會清除。';}else if(latest.version===APP_VERSION){$('#update-status').textContent='目前 v'+APP_VERSION+' 已是網站最新版本（剛剛已連網確認）。';}else{$('#update-status').textContent='網站版本 v'+latest.version+'，尚未備妥更新。請稍後重試，不要清除資料。';}}catch(e){if($('#update-status'))$('#update-status').textContent='無法確認最新版本：'+e.message+'。離線時仍可繼續記錄。';}finally{heavy=false;}}
